import { jsx as _jsx } from "react/jsx-runtime";
import { userEvent } from "@testing-library/user-event";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { GenericPageTemplate } from "..";
import { KPI_CONTAINER_VARIANT } from "../../../components/kpi";
describe("Rapid7 GenericPageTemplate", () => {
    const testIds = {
        kpiContainer: "kpi-container",
        tabPanelHeader: "generic-page-tab-panel-header",
        tabs: "generic-page-template-tabs",
    };
    const minProps = {
        detailsPageHeaderProps: {
            pageTitle: "GenericPageTitle",
        },
        tabs: [
            {
                content: "Affected Assets content",
                id: "tab1",
                label: "Affected Assets",
            },
            {
                content: "Exploits content",
                id: "tab2",
                label: "Exploits",
            },
        ],
    };
    it("should render the pageTitle and multiple tabs", () => {
        render(_jsx(GenericPageTemplate, { ...minProps }));
        const pageTitle = screen.getByText(minProps.detailsPageHeaderProps.pageTitle);
        const tab1 = screen.getByRole("tab", { name: minProps.tabs[0].label });
        const tab2 = screen.getByRole("tab", { name: minProps.tabs[1].label });
        const tabs = screen.getByTestId(testIds.tabs);
        expect(tabs).toBeInTheDocument();
        expect(pageTitle).toBeInTheDocument();
        expect(tab1).toBeInTheDocument();
        expect(tab2).toBeInTheDocument();
        expect(screen.queryByTestId(testIds.kpiContainer)).not.toBeInTheDocument();
    });
    it("should render the pageTitle and no tabs", () => {
        const props = {
            ...minProps,
            tabs: [
                {
                    content: "Exploits content",
                    id: "tab2",
                    label: "Exploits",
                },
            ],
        };
        render(_jsx(GenericPageTemplate, { ...props }));
        const tabs = screen.queryByTestId(testIds.tabs);
        const tabHeader = screen.getByTestId(testIds.tabPanelHeader);
        const heading = screen.getByRole("heading", { name: props.tabs[0].label });
        expect(tabs).not.toBeInTheDocument();
        expect(tabHeader).toBeInTheDocument();
        expect(heading).toBeInTheDocument();
    });
    it("should render no tabs without a tab header label", () => {
        const props = {
            ...minProps,
            tabs: [
                {
                    content: "Exploits content",
                    id: "tab2",
                },
            ],
        };
        render(_jsx(GenericPageTemplate, { ...props }));
        const tabs = screen.queryByTestId(testIds.tabs);
        const tabHeader = screen.queryByTestId(testIds.tabPanelHeader);
        expect(tabs).not.toBeInTheDocument();
        expect(tabHeader).not.toBeInTheDocument();
        expect(screen.getByText(props.tabs[0].content)).toBeInTheDocument();
    });
    it("should handle no tabs", () => {
        const props = {
            ...minProps,
            tabs: [],
        };
        render(_jsx(GenericPageTemplate, { ...props }));
        const genericPageTemplate = screen.queryByTestId("generic-page-template");
        expect(genericPageTemplate).not.toBeInTheDocument();
    });
    it("should render the first tabs content by default", () => {
        render(_jsx(GenericPageTemplate, { ...minProps }));
        const tab1Content = screen.getByText(minProps.tabs[0].content);
        const tab2Content = screen.queryByText(minProps.tabs[1].content);
        expect(tab1Content).toBeInTheDocument();
        expect(tab2Content).not.toBeInTheDocument();
    });
    it("should render the second tabs content when it is specified", () => {
        render(_jsx(GenericPageTemplate, { ...minProps, selectedTabIndex: 1 }));
        const tab1Content = screen.queryByText(minProps.tabs[0].content);
        const tab2Content = screen.getByText(minProps.tabs[1].content);
        expect(tab2Content).toBeInTheDocument();
        expect(tab1Content).not.toBeInTheDocument();
    });
    it("should render the first tabs content when the selectedTabIndex is greater than the number of tabs", () => {
        render(_jsx(GenericPageTemplate, { ...minProps, selectedTabIndex: 2 }));
        const tab1Content = screen.getByText(minProps.tabs[0].content);
        const tab2Content = screen.queryByText(minProps.tabs[1].content);
        expect(tab1Content).toBeInTheDocument();
        expect(tab2Content).not.toBeInTheDocument();
    });
    it("should render the first tabs content when the selectedTabIndex is less than 0", () => {
        render(_jsx(GenericPageTemplate, { ...minProps, selectedTabIndex: -1 }));
        const tab1Content = screen.getByText(minProps.tabs[0].content);
        const tab2Content = screen.queryByText(minProps.tabs[1].content);
        expect(tab1Content).toBeInTheDocument();
        expect(tab2Content).not.toBeInTheDocument();
    });
    it("should change tab content when clicking on a tab", async () => {
        const user = userEvent.setup();
        render(_jsx(GenericPageTemplate, { ...minProps }));
        expect(screen.getByText(minProps.tabs[0].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[1].content)).not.toBeInTheDocument();
        await user.click(screen.getByText(minProps.tabs[1].label));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
    });
    it("should maintain the selected tab after a re-render", async () => {
        const user = userEvent.setup();
        const tabs = [...minProps.tabs];
        const { rerender } = render(_jsx(GenericPageTemplate, { ...minProps }));
        expect(screen.getByText(minProps.tabs[0].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[1].content)).not.toBeInTheDocument();
        await user.click(screen.getByText(minProps.tabs[1].label));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
        rerender(_jsx(GenericPageTemplate, { ...minProps, tabs: tabs }));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
    });
    it("should maintain the selected tab after an additional tab has been added", async () => {
        const user = userEvent.setup();
        const tabs = [
            ...minProps.tabs,
            {
                content: "Tab 3 content",
                id: "tab3",
                label: "Tab 3",
            },
        ];
        const { rerender } = render(_jsx(GenericPageTemplate, { ...minProps }));
        expect(screen.getByText(minProps.tabs[0].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[1].content)).not.toBeInTheDocument();
        await user.click(screen.getByText(minProps.tabs[1].label));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
        rerender(_jsx(GenericPageTemplate, { ...minProps, tabs: tabs }));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
    });
    it("should update the selected tab when the selectedTabIndex prop changes", () => {
        const { rerender } = render(_jsx(GenericPageTemplate, { ...minProps }));
        expect(screen.getByText(minProps.tabs[0].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[1].content)).not.toBeInTheDocument();
        rerender(_jsx(GenericPageTemplate, { ...minProps, selectedTabIndex: 1 }));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
    });
    it("should render the first tabs content when the current tab is removed from the tabs prop", () => {
        const props = {
            ...minProps,
            selectedTabIndex: 1,
        };
        const { rerender } = render(_jsx(GenericPageTemplate, { ...props }));
        expect(screen.getByText(minProps.tabs[1].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[0].content)).not.toBeInTheDocument();
        rerender(_jsx(GenericPageTemplate, { ...props, tabs: [minProps.tabs[0]] }));
        expect(screen.getByText(minProps.tabs[0].content)).toBeInTheDocument();
        expect(screen.queryByText(minProps.tabs[1].content)).not.toBeInTheDocument();
    });
    it("should render KPIs when KPI container props provided", () => {
        const kpiContainerProps = {
            childrenPerRow: 3,
            kpis: [
                {
                    label: "KPI Label 1",
                    value: 1,
                },
                {
                    label: "KPI Label 2",
                    value: 2,
                },
            ],
            variant: KPI_CONTAINER_VARIANT.CARD,
        };
        const propsWithKpiContainer = {
            ...minProps,
            kpiContainerProps,
        };
        render(_jsx(GenericPageTemplate, { ...propsWithKpiContainer }));
        expect(screen.getByTestId(testIds.kpiContainer)).toBeInTheDocument();
        expect(screen.getByText("KPI Label 1")).toBeInTheDocument();
        expect(screen.getByText("KPI Label 2")).toBeInTheDocument();
        expect(screen.getByText("1")).toBeInTheDocument();
        expect(screen.getByText("2")).toBeInTheDocument();
    });
});
